begin;
set local search_path=public,extensions;
select no_plan();
insert into public.cities values('regional-test','Regional fixture','BC','America/Vancouver',true),('regional-other','Other fixture','BC','America/Vancouver',true);
insert into auth.users(id,email) values('e2440000-0000-4000-8000-000000000001','regional-owner@example.test');
insert into public.profiles(id,nickname,city_id) values('e2440000-0000-4000-8000-000000000001','RegionalOwner','regional-test');
insert into private.city_place_catalog(id,payload,refreshed_on) values(true,'{"cities":{"regional-test":{"places":[{"id":"osm:node:710001","cityId":"regional-test","name":"Existing base","address":"Base address","category":"places","latitude":49.2,"longitude":-123.1,"sourceUrl":"https://www.openstreetmap.org/node/710001"}],"regionalPlaces":[{"id":"osm:node:710001","cityId":"regional-test","name":"Must not override base","address":"Wrong replacement","category":"places","latitude":49.2,"longitude":-123.1,"sourceUrl":"https://www.openstreetmap.org/node/710001"},{"id":"osm:node:710002","cityId":"regional-test","name":"Regional park","address":"Real Road, Coquitlam, BC","category":"places","latitude":49.3,"longitude":-122.8,"sourceUrl":"https://www.openstreetmap.org/node/710002"},{"id":"osm:node:710003","cityId":"regional-test","name":"Forged source","address":"Fake","category":"places","latitude":49.3,"longitude":-122.8,"sourceUrl":"https://example.org/forged"},{"id":"osm:node:710004","cityId":"regional-other","name":"Wrong city","address":"Other","category":"places","latitude":49.3,"longitude":-122.8,"sourceUrl":"https://www.openstreetmap.org/node/710004"},{"id":"osm:node:710005","cityId":"regional-test","name":"Invalid location","address":"Wrong coordinates","category":"places","latitude":0,"longitude":0,"sourceUrl":"https://www.openstreetmap.org/node/710005"}]}},"collectedAt":"2026-10-24T00:00:00Z"}',current_date) on conflict(id) do update set payload=excluded.payload;
select set_config('request.jwt.claims','{"sub":"e2440000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is(public.get_saved_item_state('place','osm:node:710002','regional-test')->>'available','true','regional source is a real available saved target');
select lives_ok($$select public.set_saved_item('place','osm:node:710002',true,'regional-test')$$,'actual save API admits reviewed regional identity');
select is(public.get_saved_item_state('place','osm:node:710002','regional-test')->>'saved','true','saved flag uses exact regional identity');
select is(public.get_saved_items()->'items'->0->>'title','Regional park','library hydrates regional name from trusted catalog');
select is(public.get_saved_items()->'items'->0->>'address','Real Road, Coquitlam, BC','library keeps actual municipality');
select lives_ok($$select public.set_saved_item('place','osm:node:710001',true,'regional-test')$$,'legacy base remains saveable');
select throws_ok($$select public.set_saved_item('place','osm:node:710003',true,'regional-test')$$,'P0001','SAVED_TARGET_UNAVAILABLE','regional source guard remains authoritative');
select throws_ok($$select public.set_saved_item('place','osm:node:710004',true,'regional-test')$$,'P0001','SAVED_TARGET_UNAVAILABLE','cross-city regional identity rejected');
select throws_ok($$select public.set_saved_item('place','osm:node:710005',true,'regional-test')$$,'P0001','SAVED_TARGET_UNAVAILABLE','invalid regional coordinates rejected');
select throws_ok($$select public.set_saved_item('place','osm:node:710002',true,'regional-other')$$,'P0001','SAVED_TARGET_UNAVAILABLE','same key cannot be saved under another city');
reset role;
select ok(not has_function_privilege('authenticated','private.saved_place_info(text,text)','execute'),'private resolver remains inaccessible directly');
select is(private.saved_place_info('regional-test','osm:node:710001')->>'name','Existing base','base projection wins duplicate regional identity');
update private.city_place_catalog set payload=jsonb_set(payload,'{cities,regional-test,regionalPlaces}','[]'::jsonb);
set local role authenticated;
select is(public.get_saved_item_state('place','osm:node:710002','regional-test')->>'available','false','explicit removal makes regional target unavailable');
select lives_ok($$select public.set_saved_item('place','osm:node:710002',false,'regional-test')$$,'removed regional target can still be unsaved');
select is(public.get_saved_item_state('place','osm:node:710002','regional-test')->>'saved','false','removed regional save is cleared');
reset role;
update private.city_place_catalog set payload=jsonb_set(payload,'{cities,regional-test,regionalPlaces}','{"malformed":true}'::jsonb);
select is(private.saved_place_info('regional-test','osm:node:710001')->>'name','Existing base','malformed optional group cannot break legacy lookup');
select is(private.saved_place_info('regional-test','osm:node:710002'),null::jsonb,'malformed optional group admits no identity');
-- The initial trusted metadata is independent of the daily city-catalog write.
select set_config('test.regional_initial',$regional_expected$[{"city_id":"vancouver","place_key":"osm:way:41745659","name":"Town Centre Park","address":"1299 Pinetree Way, Coquitlam, BC, Canada"},{"city_id":"vancouver","place_key":"osm:way:41843304","name":"Como Lake Park","address":"700 Gatensbury Street, Coquitlam, BC, Canada"},{"city_id":"vancouver","place_key":"osm:way:41841917","name":"Blue Mountain Park","address":"975 King Albert Avenue, Coquitlam, BC, Canada"},{"city_id":"vancouver","place_key":"osm:way:1004996176","name":"Mundy Park","address":"641 Hillcrest Street, Coquitlam, BC, Canada"},{"city_id":"vancouver","place_key":"osm:relation:21109172","name":"Minnekhada Regional Park","address":"Quarry Road entrance, Coquitlam, BC, Canada"},{"city_id":"vancouver","place_key":"osm:way:42472552","name":"Gates Park","address":"2300 Reeve Street, Port Coquitlam, BC, Canada"},{"city_id":"vancouver","place_key":"osm:way:212904864","name":"Lions Park","address":"2300 Lions Way, Port Coquitlam, BC, Canada"},{"city_id":"vancouver","place_key":"osm:relation:1304120","name":"Queen's Park","address":"Queen's Park, New Westminster, BC, Canada"},{"city_id":"vancouver","place_key":"osm:way:170530924","name":"Westminster Pier Park","address":"Westminster Pier Park, Fourth Street / Sixth Street overpass access, New Westminster, BC, Canada"},{"city_id":"vancouver","place_key":"osm:node:9381204484","name":"Port Coquitlam Cenotaph","address":"Veterans Park, 2580 Shaughnessy Street, Port Coquitlam, BC, Canada"}]$regional_expected$,true);
select is((select jsonb_agg(jsonb_build_object('city_id',s.city_id,'place_key',s.place_key,'name',s.name,'address',s.address) order by s.place_key)
 from private.saved_partner_places s where s.city_id='vancouver' and s.place_key in(select value->>'place_key' from jsonb_array_elements(current_setting('test.regional_initial')::jsonb))),
 (select jsonb_agg(value order by value->>'place_key')from jsonb_array_elements(current_setting('test.regional_initial')::jsonb)),
 'migration seeds exactly the ten source-reviewed initial tuples');
-- Make the tombstone regression meaningful even on the pre-fix migration.
insert into private.saved_partner_places(city_id,place_key,name,address)
 select value->>'city_id',value->>'place_key',value->>'name',value->>'address' from jsonb_array_elements(current_setting('test.regional_initial')::jsonb) on conflict do nothing;
update private.city_place_catalog set payload='{"selectionRevision":25,"cities":{"vancouver":{"places":[]}}}'::jsonb;
set local role authenticated;
select lives_ok(format('select public.set_saved_item(%L,%L,true,%L)','place',value->>'place_key','vancouver'),'omitted extension admits initial '||(value->>'name')) from jsonb_array_elements(current_setting('test.regional_initial')::jsonb);
select is(public.get_saved_item_state('place',value->>'place_key','vancouver')->>'saved','true','initial saved flag '||(value->>'name'))from jsonb_array_elements(current_setting('test.regional_initial')::jsonb);
select is(public.get_saved_item_state('place',value->>'place_key','vancouver')->'target'->>'kind','place','initial metadata does not invent a merchant '||(value->>'name'))from jsonb_array_elements(current_setting('test.regional_initial')::jsonb);
select is((select jsonb_agg(jsonb_build_object('city_id',item->'target'->>'cityId','place_key',item->'target'->>'id','name',item->>'title','address',item->>'address') order by item->'target'->>'id')from jsonb_array_elements(public.get_saved_items()->'items')item where item->'target'->>'cityId'='vancouver'),
 (select jsonb_agg(value order by value->>'place_key')from jsonb_array_elements(current_setting('test.regional_initial')::jsonb)),'initial ten hydrate exact reviewed names and addresses');
select is(public.get_saved_item_state('place','osm:node:999999999999','vancouver')->>'available','false','unknown OSM key has no invented static metadata');
select is(public.get_saved_item_state('place','osm:way:41745659','regional-other')->>'available','false','static key cannot cross cities');
reset role;
update private.city_place_catalog set payload=jsonb_set(payload,'{cities,vancouver,places}','[{"id":"osm:way:41745659","cityId":"vancouver","name":"Live base name","address":"Live base address","category":"places","latitude":49.2,"longitude":-123.1,"sourceUrl":"https://www.openstreetmap.org/way/41745659"}]'::jsonb);
select is(private.saved_place_info('vancouver','osm:way:41745659')->>'name','Live base name','live base wins over initial static metadata');
update private.city_place_catalog set payload=jsonb_set(jsonb_set(payload,'{cities,vancouver,places}','[]'::jsonb),'{cities,vancouver,regionalPlaces}','[{"id":"osm:way:41745659","cityId":"vancouver","name":"Live regional rename","address":"Updated regional address","category":"places","latitude":49.2,"longitude":-123.1,"sourceUrl":"https://www.openstreetmap.org/way/41745659"}]'::jsonb);
select is(private.saved_place_info('vancouver','osm:way:41745659')->>'name','Live regional rename','authoritative regional rename wins over initial static metadata');
select is(private.saved_place_info('vancouver','osm:way:41843304'),null::jsonb,'present array makes removed static identity unavailable');
update private.city_place_catalog set payload=jsonb_set(payload,'{cities,vancouver,regionalPlaces}','[]'::jsonb);
select is(private.saved_place_info('vancouver','osm:way:41745659'),null::jsonb,'explicit empty array is an OSM tombstone');
set local role authenticated;
select is(public.get_saved_item_state('place','osm:way:41745659','vancouver')->>'available','false','public state honors the explicit tombstone');
select throws_ok($$select public.set_saved_item('place','osm:way:41745659',true,'vancouver')$$,'P0001','SAVED_TARGET_UNAVAILABLE','save cannot resurrect a tombstoned initial place');
reset role;
select is(private.saved_place_info('vancouver','partner:jimoco-coquitlam')->>'name','Jimoco Café & Pasta','Jimoco partner fallback unchanged with empty regional array');
select is(private.saved_place_info('vancouver','partner:on-and-off-coquitlam')->>'name','On & Off Kitchen + Bar','OnOff partner fallback unchanged with empty regional array');
update private.city_place_catalog set payload=jsonb_set(payload,'{cities,vancouver,regionalPlaces}','null'::jsonb);
select is(private.saved_place_info('vancouver','osm:way:41745659'),null::jsonb,'explicit JSON null fails closed for static OSM identities');
update private.city_place_catalog set payload=jsonb_set(payload,'{cities,vancouver,regionalPlaces}','{"bad":true}'::jsonb);
select is(private.saved_place_info('vancouver','osm:way:41745659'),null::jsonb,'malformed object fails closed for static OSM identities');
select is(private.saved_place_info('vancouver','partner:jimoco-coquitlam')->>'name','Jimoco Café & Pasta','partner fallback survives malformed OSM regional metadata');
set local role authenticated;
select lives_ok(format('select public.set_saved_item(%L,%L,false,%L)','place',value->>'place_key','vancouver'),'unavailable initial identity can be unsaved '||(value->>'name'))from jsonb_array_elements(current_setting('test.regional_initial')::jsonb);
select is(jsonb_array_length(public.get_saved_items()->'items'),0,'initial ten are removed from the current library');
select is(public.get_saved_item_state('place','osm:node:710001','regional-test')->>'saved','true','unsaving initial identities preserves the unrelated prior save');
reset role;
update private.city_place_catalog set payload=payload#-'{cities,vancouver,regionalPlaces}';
update public.profiles set account_status='suspended' where id='e2440000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.get_saved_item_state('place','osm:way:41745659','vancouver')$$,'P0001','ACCOUNT_LOCKED','inactive account cannot read static saved target state');
select throws_ok($$select public.set_saved_item('place','osm:way:41745659',true,'vancouver')$$,'P0001','ACCOUNT_LOCKED','inactive account cannot save initial metadata');
reset role;
update public.profiles set account_status='active' where id='e2440000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.get_saved_item_state('place','osm:way:41745659','vancouver')$$,'P0001','AUTH_REQUIRED','missing authenticated identity still denied');
select throws_ok($$select public.set_saved_item('place','osm:way:41745659',true,'vancouver')$$,'P0001','AUTH_REQUIRED','missing identity cannot save initial metadata');
reset role;
select ok(not has_table_privilege('authenticated','private.saved_partner_places','select'),'static metadata table remains private');
select ok(not has_function_privilege('anon','public.get_saved_item_state(text,text,text)','execute'),'anonymous saved state has no new grant');
select ok((select relrowsecurity from pg_class where oid='private.saved_partner_places'::regclass),'existing static metadata RLS remains enabled');
select is((select pg_get_userbyid(relowner) from pg_class where oid='private.saved_partner_places'::regclass),'postgres','existing static table owner is preserved');
insert into private.merchants(id,city_id) values('e2440000-0000-4000-8000-000000000002','regional-other');
insert into private.webshop_place_links(place_key,city_id,merchant_id) values('osm:way:41745659','regional-other','e2440000-0000-4000-8000-000000000002');
select is(private.saved_place_info('vancouver','osm:way:41745659'),null::jsonb,'linked-business cross-city guard still rejects static metadata');
select * from finish();
rollback;
